let revision = 0
let rows = [
  { id: 'north', label: 'North', score: 40 },
  { id: 'south', label: 'South', score: 20 },
  { id: 'west', label: 'West', score: 30 },
]
const listeners = new Set()

function snapshot() {
  return {
    revision,
    rows: rows.map((row) => ({ ...row })),
  }
}

export function subscribe(listener) {
  listeners.add(listener)
  listener(snapshot())
  return () => listeners.delete(listener)
}

export function updateLabel(id, label) {
  rows = rows.map((row) => ({ ...row, label: row.id === id ? label : row.label }))
  revision += 1
  const value = snapshot()
  for (const listener of [...listeners]) listener(value)
}

export function getRows() {
  return rows
}

import { getRows, subscribe, updateLabel } from './src/store.mjs'

const before = new Map(getRows().map((row) => [row.id, row]))
const events = []
subscribe((value) => {
  events.push({
    revision: value.revision,
    order: value.rows.map((row) => row.id),
    changedFromBefore:
      events.length === 0 ? value.rows.filter((row) => before.get(row.id) !== row).map((row) => row.id) : undefined,
  })
})
updateLabel('south', 'South updated')

console.log(
  JSON.stringify(
    {
      events,
      retainedIdentityByRow: Object.fromEntries(getRows().map((row) => [row.id, before.get(row.id) === row])),
    },
    null,
    2,
  ),
)
